package br.com.erp.purchase;
import br.com.erp.auth.*;
import br.com.erp.shared.*;
import br.com.erp.inventory.StockService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.*;
import org.springframework.web.bind.annotation.*;

@br.com.erp.shared.WorkflowAmounts @RestController @RequestMapping("/api/v1/supplier-returns") @PreAuthorize("hasAuthority('purchase:read') and hasAuthority('inventory:read') and hasAuthority('payable:read')")
public class SupplierReturnController {
 private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final StockService stock;private final Audit audit;
 public SupplierReturnController(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,StockService stock,Audit audit){this.db=db;this.access=access;this.flow=flow;this.stock=stock;this.audit=audit;}
 public record Line(@NotNull UUID orderLineId,@NotNull @DecimalMin(value="0",inclusive=false) @Digits(integer=13,fraction=6) BigDecimal quantity){}
 public record Input(@NotNull UUID requestId,@NotNull UUID receiptId,@NotBlank @Size(min=5,max=500) String note,@NotEmpty @Size(max=100) List<@NotNull @Valid Line> items,@DecimalMin("0") @Digits(integer=17,fraction=2) BigDecimal expectedAmount,@DecimalMin("0") @Digits(integer=17,fraction=2) BigDecimal expectedDebtCredit,@DecimalMin("0") @Digits(integer=17,fraction=2) BigDecimal expectedSupplierCredit){}
 private Map<String,Object> receipt(Actor a,UUID id){var rows=db.queryForList("SELECT r.warehouse_id,o.branch_id,o.supplier_id FROM purchase_receipt r JOIN purchase_order o ON o.tenant_id=r.tenant_id AND o.id=r.order_id WHERE r.tenant_id=? AND r.id=?",a.tenantId(),id);if(rows.isEmpty())throw flow.missing("Recebimento não encontrado.");var r=rows.getFirst();access.requireBranch(a,(UUID)r.get("branch_id"));access.requireWarehouse(a,(UUID)r.get("warehouse_id"));return r;}
 @GetMapping("/receipt/{receiptId}") @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> detail(@AuthenticationPrincipal Actor a,@PathVariable UUID receiptId){var r=receipt(a,receiptId);var lines=db.queryForList("SELECT l.order_line_id,p.sku,p.name,p.unit,l.quantity,l.amount,COALESCE((SELECT SUM(x.quantity) FROM supplier_return_line x JOIN supplier_return h ON h.tenant_id=x.tenant_id AND h.id=x.return_id WHERE x.tenant_id=l.tenant_id AND h.receipt_id=l.receipt_id AND x.order_line_id=l.order_line_id),0) AS returned_quantity FROM purchase_receipt_line l JOIN purchase_order_line p ON p.tenant_id=l.tenant_id AND p.id=l.order_line_id WHERE l.tenant_id=? AND l.receipt_id=? ORDER BY p.product_id",a.tenantId(),receiptId);return Map.of("receipt",r,"items",lines,"returns",db.queryForList("SELECT * FROM supplier_return WHERE tenant_id=? AND receipt_id=? ORDER BY created_at DESC,id",a.tenantId(),receiptId));}
 @PostMapping @PreAuthorize("hasAuthority('purchase:read') and hasAuthority('purchase:write') and hasAuthority('inventory:read') and hasAuthority('inventory:write') and hasAuthority('payable:read') and hasAuthority('payable:write')") @Transactional
 public Map<String,Object> create(@AuthenticationPrincipal Actor a,@Valid @RequestBody Input input){flow.lock(a);var scope=receipt(a,input.receiptId());String note=input.note().trim();if(note.length()<5)throw flow.bad("Informe justificativa com cinco caracteres.");var sorted=input.items().stream().sorted(Comparator.comparing(l->l.orderLineId().toString())).toList();var fields=new ArrayList<Object>(Arrays.asList("SUPPLIER_RETURN",input.receiptId(),note,input.expectedAmount(),input.expectedDebtCredit(),input.expectedSupplierCredit()));var seen=new HashSet<UUID>();for(var l:sorted){if(!seen.add(l.orderLineId()))throw flow.bad("Item repetido.");Collections.addAll(fields,l.orderLineId(),l.quantity());}String hash=flow.hash(fields.toArray());UUID old=flow.replay(a,input.requestId(),"SUPPLIER_RETURN",hash);if(old!=null)return result(a,old);
 UUID id=UUID.randomUUID();var plan=plan(a,input);var prepared=plan.prepared();BigDecimal total=plan.total(),debt=plan.debt(),credit=plan.credit();
 if(input.expectedAmount()==null||input.expectedDebtCredit()==null||input.expectedSupplierCredit()==null)throw flow.bad("Confira a prévia financeira antes de devolver.");
 if(total.compareTo(input.expectedAmount())!=0||debt.compareTo(input.expectedDebtCredit())!=0||credit.compareTo(input.expectedSupplierCredit())!=0)throw flow.conflict("Valores ou pagamentos mudaram. Atualize a prévia antes de confirmar.");
 db.update("INSERT INTO supplier_return(id,tenant_id,receipt_id,branch_id,supplier_id,amount,debt_credit,supplier_credit,note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)",id,a.tenantId(),input.receiptId(),scope.get("branch_id"),scope.get("supplier_id"),total,debt,credit,note,a.userId());
 prepared.sort(Comparator.comparing(r->r.get("product_id").toString()));for(var row:prepared){var l=(Line)row.get("line");UUID op=UUID.randomUUID();stock.returnSupplier(a,op,id,(UUID)scope.get("warehouse_id"),(UUID)row.get("product_id"),(String)row.get("unit"),l.quantity(),note);db.update("INSERT INTO supplier_return_line(tenant_id,return_id,receipt_id,order_line_id,quantity,amount,operation_id) VALUES(?,?,?,?,?,?,?)",a.tenantId(),id,input.receiptId(),l.orderLineId(),l.quantity(),row.get("return_amount"),op);}
 BigDecimal remaining=debt;for(var title:db.queryForList("SELECT id,amount,paid_amount,credited_amount FROM payable WHERE tenant_id=? AND purchase_receipt_id=? AND status IN ('OPEN','PARTIAL') ORDER BY due_on DESC,id FOR UPDATE",a.tenantId(),input.receiptId())){if(remaining.signum()==0)break;BigDecimal amount=(BigDecimal)title.get("amount"),paid=(BigDecimal)title.get("paid_amount"),credited=(BigDecimal)title.get("credited_amount"),part=remaining.min(amount.subtract(paid).subtract(credited));if(part.signum()==0)continue;credited=credited.add(part);String status=paid.add(credited).compareTo(amount)==0?"CREDITED":paid.signum()>0?"PARTIAL":"OPEN";db.update("UPDATE payable SET credited_amount=?,status=?,version=version+1 WHERE tenant_id=? AND id=?",credited,status,a.tenantId(),title.get("id"));db.update("INSERT INTO supplier_return_debt_credit(tenant_id,return_id,payable_id,amount) VALUES(?,?,?,?)",a.tenantId(),id,title.get("id"),part);remaining=remaining.subtract(part);}
 flow.record(a,input.requestId(),"SUPPLIER_RETURN",hash,id);audit.record(a,"SUPPLIER_RETURN_CREATED",id);return result(a,id);
 }
 private record Plan(List<Map<String,Object>> prepared,BigDecimal total,BigDecimal debt,BigDecimal credit,boolean financed){}
 private Plan plan(Actor a,Input input){var sorted=input.items().stream().sorted(Comparator.comparing(l->l.orderLineId().toString())).toList();if(sorted.stream().map(Line::orderLineId).distinct().count()!=sorted.size())throw flow.bad("Item repetido.");
 boolean financed=db.queryForObject("SELECT COUNT(*) FROM purchase_receipt_finance WHERE tenant_id=? AND receipt_id=?",Long.class,a.tenantId(),input.receiptId())>0;
 if(db.queryForObject("SELECT COUNT(*) FROM payable p WHERE p.tenant_id=? AND p.purchase_receipt_id=? AND (p.status='CANCELLED' OR NOT EXISTS(SELECT 1 FROM purchase_receipt_installment i WHERE i.tenant_id=p.tenant_id AND i.payable_id=p.id))",Long.class,a.tenantId(),input.receiptId())>0)throw flow.conflict("Reconcilie títulos manuais/cancelados antes de devolver.");
 BigDecimal total=BigDecimal.ZERO;var prepared=new ArrayList<Map<String,Object>>();
 for(var l:sorted){var rows=db.queryForList("SELECT p.product_id,p.unit,r.quantity,r.amount FROM purchase_receipt_line r JOIN purchase_order_line p ON p.tenant_id=r.tenant_id AND p.id=r.order_line_id WHERE r.tenant_id=? AND r.receipt_id=? AND r.order_line_id=?",a.tenantId(),input.receiptId(),l.orderLineId());if(rows.isEmpty())throw flow.missing("Item não pertence ao recebimento.");var row=rows.getFirst();BigDecimal prior=db.queryForObject("SELECT COALESCE(SUM(x.quantity),0) FROM supplier_return_line x JOIN supplier_return h ON h.tenant_id=x.tenant_id AND h.id=x.return_id WHERE x.tenant_id=? AND h.receipt_id=? AND x.order_line_id=?",BigDecimal.class,a.tenantId(),input.receiptId(),l.orderLineId());BigDecimal qty=(BigDecimal)row.get("quantity"),amount=(BigDecimal)row.get("amount"),after=prior.add(l.quantity());if(after.compareTo(qty)>0)throw flow.conflict("Quantidade supera o saldo recebido.");BigDecimal value=amount.multiply(after).divide(qty,2,RoundingMode.HALF_UP).subtract(amount.multiply(prior).divide(qty,2,RoundingMode.HALF_UP));row.put("return_amount",value);row.put("line",l);prepared.add(row);total=total.add(value);}
 BigDecimal available=financed?db.queryForObject("SELECT COALESCE(SUM(amount-paid_amount-credited_amount),0) FROM payable WHERE tenant_id=? AND purchase_receipt_id=? AND status<>'CANCELLED'",BigDecimal.class,a.tenantId(),input.receiptId()):BigDecimal.ZERO;
 BigDecimal debt=financed?total.min(available):BigDecimal.ZERO,credit=financed?total.subtract(debt):BigDecimal.ZERO;
 return new Plan(prepared,total,debt,credit,financed);
 }
 @PostMapping("/preview") @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> preview(@AuthenticationPrincipal Actor a,@Valid @RequestBody Input input){receipt(a,input.receiptId());var p=plan(a,input);return Map.of("amount",p.total(),"debtCredit",p.debt(),"supplierCredit",p.credit(),"financed",p.financed());}
 private Map<String,Object> result(Actor a,UUID id){return db.queryForMap("SELECT * FROM supplier_return WHERE tenant_id=? AND id=?",a.tenantId(),id);}
}
